def _help_spielb(doc, lang):
    i = doc.find('<section id="games"')
    j = doc.find("</ul>", i) if i >= 0 else -1
    if j < 0 or "/game/…/" in doc[i:j]:
        return doc
    return doc[:j] + _HELP_SPIELB[lang] + doc[j:]


